"""One-off generator for tests/contracts samples and schemas (scratch, not project code)."""

from __future__ import annotations

import dataclasses
import json
import sys
import types
import typing
from collections.abc import Mapping
from datetime import UTC, datetime, timedelta
from pathlib import Path
from typing import Any, Literal, get_args, get_origin, get_type_hints

import numpy as np

from rllab.baselines import BaselineMeans
from rllab.core import (
    EVAL_SEEDS,
    FINAL_SEEDS,
    Box,
    Discrete,
    Drawable,
    DrawState,
    Episode,
    EpisodeResult,
    Frame,
    MeasureSpec,
    MethodConfig,
    Output,
    RunConfig,
    Step,
    TeamSpec,
    WorldSpec,
)
from rllab.core.codec import decode_hint, encode
from rllab.core.types import ActionSpace, Array
from rllab.evaluate import Comparison, Summary, Verdict
from rllab.methods import Transition
from rllab.runlog import Checkpoint, EvalPoint, Failure, Progress, RunRecord
from rllab.train import CheckResult

OUT = Path(sys.argv[1])
f32 = np.float32


# ----------------------------------------------------------------------------- schema
def schema(hint: Any, defs: dict[str, Any]) -> dict[str, Any]:
    if hint is Any or hint is object:
        return {}
    origin = get_origin(hint)
    if origin in (typing.Union, types.UnionType):
        return {"anyOf": [schema(a, defs) for a in get_args(hint)]}
    if origin is Literal:
        return {"enum": list(get_args(hint))}
    if hint is np.ndarray or origin is np.ndarray:
        defs.setdefault(
            "Array",
            {
                "type": "object",
                "properties": {
                    "dtype": {"enum": ["float32", "float64", "int64", "bool"]},
                    "shape": {"type": "array", "items": {"type": "integer", "minimum": 0}},
                    "data": {"type": ["array", "number", "integer", "boolean"]},
                },
                "required": ["dtype", "shape", "data"],
                "additionalProperties": False,
            },
        )
        return {"$ref": "#/$defs/Array"}
    if origin is tuple:
        args = get_args(hint)
        if len(args) == 2 and args[1] is Ellipsis:
            return {"type": "array", "items": schema(args[0], defs)}
        return {
            "type": "array",
            "prefixItems": [schema(a, defs) for a in args],
            "minItems": len(args),
            "maxItems": len(args),
        }
    if origin in (Mapping, dict):
        return {"type": "object", "additionalProperties": schema(get_args(hint)[1], defs)}
    if isinstance(hint, type) and dataclasses.is_dataclass(hint):
        name = hint.__name__
        if name not in defs:
            defs[name] = {}
            hints = get_type_hints(hint)
            fields = dataclasses.fields(hint)
            defs[name] = {
                "type": "object",
                "properties": {f.name: schema(hints[f.name], defs) for f in fields},
                "required": [
                    f.name
                    for f in fields
                    if f.default is dataclasses.MISSING and f.default_factory is dataclasses.MISSING
                ],
                "additionalProperties": False,
            }
        return {"$ref": f"#/$defs/{name}"}
    leaf = {
        int: {"type": "integer"},
        float: {"type": "number"},
        str: {"type": "string"},
        bool: {"type": "boolean"},
        type(None): {"type": "null"},
        Path: {"type": "string"},
        datetime: {"type": "string"},
        timedelta: {"type": "number", "minimum": 0},
    }
    return dict(leaf[hint])


INVARIANTS: dict[str, dict[str, dict[str, Any]]] = {
    "Discrete": {"n": {"minimum": 1}},
    "Box": {"dims": {"minimum": 1}},
    "CheckResult": {"agreement": {"minimum": 0, "maximum": 1}},
    "Checkpoint": {"pct": {"enum": list(range(0, 101, 10))}, "step": {"minimum": 0}},
    "WorldSpec": {"obs_len": {"minimum": 1}, "max_steps": {"minimum": 1}},
    "EpisodeResult": {"length": {"minimum": 0}},
    "RunConfig": {"budget": {"minimum": 1}, "seed": {"minimum": 0}},
    "Comparison": {"p_raw": {"minimum": 0, "maximum": 1}, "p_holm": {"minimum": 0, "maximum": 1}},
    "Verdict": {"runs_needed": {"minimum": 0}},
    "Progress": {"step": {"minimum": 0}, "budget": {"minimum": 1}},
}


def document(symbol: str, root: dict[str, Any], defs: dict[str, Any]) -> dict[str, Any]:
    for name, props in INVARIANTS.items():
        if name in defs:
            for prop, extra in props.items():
                defs[name]["properties"][prop].update(extra)
    doc = {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": symbol}
    doc.update(root)
    if defs:
        doc["$defs"] = dict(sorted(defs.items()))
    return doc


def type_schema(symbol: str, hint: Any) -> dict[str, Any]:
    defs: dict[str, Any] = {}
    return document(symbol, schema(hint, defs), defs)


def obj(props: dict[str, Any], defs_hints: dict[str, Any], defs: dict[str, Any]) -> dict[str, Any]:
    """An object schema whose properties are hints or ready schemas."""
    return {
        "type": "object",
        "properties": {
            k: (v if isinstance(v, dict) else schema(v, defs)) for k, v in props.items()
        },
        "required": list(props),
        "additionalProperties": False,
    }


def write(symbol: str, doc: dict[str, Any] | None, samples: dict[str, Any]) -> None:
    folder = OUT / symbol
    (folder / "samples").mkdir(parents=True, exist_ok=True)
    if doc is not None:
        (folder / "schema.json").write_text(json.dumps(doc, indent=1) + "\n", encoding="utf-8")
    for case, value in samples.items():
        data = value if isinstance(value, dict | list) and not dataclasses.is_dataclass(value) else encode(value)
        (folder / "samples" / f"{case}.json").write_text(
            json.dumps(data, indent=1) + "\n", encoding="utf-8"
        )


def arr(values: Any, dtype: Any) -> np.ndarray:
    return np.asarray(values, dtype=dtype)


# ------------------------------------------------------------------------ snake sim
DIRS = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # up, right, down, left
LEFT, RIGHT, STRAIGHT = 0, 1, 2
SNAKE_TEAM = TeamSpec("snake", (0,), "food", "higher")


def snake_spec(max_steps: int) -> WorldSpec:
    return WorldSpec("snake", "default", ("snake",), (SNAKE_TEAM,), 12, Discrete(3), max_steps, (), None)


class Sim:
    def __init__(self, food: list[tuple[int, int]]) -> None:
        self.body = [(5, 5), (5, 6), (5, 7)]
        self.heading = 0
        self.foods = list(food)
        self.food = self.foods.pop(0)
        self.eaten = 0

    def turn(self, action: int) -> int:
        return {LEFT: (self.heading - 1) % 4, RIGHT: (self.heading + 1) % 4, STRAIGHT: self.heading}[action]

    def deadly(self, heading: int) -> bool:
        hx, hy = self.body[0]
        x, y = hx + DIRS[heading][0], hy + DIRS[heading][1]
        return not (0 <= x < 10 and 0 <= y < 10) or (x, y) in self.body[:-1]

    def obs(self) -> list[float]:
        hx, hy = self.body[0]
        fx, fy = self.food
        danger = [float(self.deadly(self.turn(a))) for a in (STRAIGHT, LEFT, RIGHT)]
        heading = [float(i == self.heading) for i in range(4)]
        food = [float(fy < hy), float(fx > hx), float(fy > hy), float(fx < hx)]
        return danger + heading + food + [float(len(self.body))]

    def rule(self) -> int:
        hx, hy = self.body[0]
        fx, fy = self.food
        dx, dy = fx - hx, fy - hy
        if dx == 0 or (dy != 0 and abs(dy) <= abs(dx)):
            want = 0 if dy < 0 else 2
        else:
            want = 1 if dx > 0 else 3
        order = [a for a in (STRAIGHT, LEFT, RIGHT) if self.turn(a) == want] or [LEFT]
        for a in order + [STRAIGHT, LEFT, RIGHT]:
            if not self.deadly(self.turn(a)):
                return a
        return STRAIGHT

    def step(self, action: int) -> float:
        self.heading = self.turn(action)
        hx, hy = self.body[0]
        head = (hx + DIRS[self.heading][0], hy + DIRS[self.heading][1])
        self.body.insert(0, head)
        if head == self.food:
            self.eaten += 1
            self.food = self.foods.pop(0)
            return 1.0
        self.body.pop()
        return 0.0

    def draw(self) -> DrawState:
        objects = [Drawable("head", *map(float, self.body[0]), 1.0, "snake", 0)]
        objects += [Drawable("body", float(x), float(y), 1.0, "snake", 0) for x, y in self.body[1:]]
        objects.append(Drawable("food", float(self.food[0]), float(self.food[1]), 1.0, None, None))
        return DrawState(10.0, 10.0, tuple(objects))


def play(food: list[tuple[int, int]], steps: int) -> dict[str, Any]:
    sim = Sim(food)
    obs = [sim.obs()]
    draws = [sim.draw()]
    actions, rewards, scores = [], [], [0.0]
    for _ in range(steps):
        a = sim.rule()
        actions.append(a)
        rewards.append(sim.step(a))
        obs.append(sim.obs())
        draws.append(sim.draw())
        scores.append(float(sim.eaten))
    return {"obs": obs, "draws": draws, "actions": actions, "rewards": rewards, "scores": scores}


def snake_steps(ep: dict[str, Any], n: int) -> list[Step]:
    out = [Step(arr([ep["obs"][0]], f32), arr([0.0], f32), arr([True], bool), False, False)]
    for t in range(1, n + 1):
        last = t == n
        out.append(
            Step(arr([ep["obs"][t]], f32), arr([ep["rewards"][t - 1]], f32), arr([True], bool), last, last)
        )
    return out


EP42 = play([(5, 2), (2, 1), (7, 7)], 5)
EP7 = play([(8, 5), (8, 8), (1, 1)], 5)
STEPS42 = snake_steps(EP42, 5)


def snake_result(seed: int, ep: dict[str, Any]) -> EpisodeResult:
    s = ep["scores"][-1]
    return EpisodeResult(seed, len(ep["actions"]), {"snake": s}, {"snake": float(sum(ep["rewards"]))}, {})


def frames(ep: dict[str, Any]) -> tuple[Frame, ...]:
    out = [Frame(0, ep["draws"][0], {"snake": 0.0}, arr([0.0], f32))]
    for t in range(1, len(ep["actions"]) + 1):
        out.append(Frame(t, ep["draws"][t], {"snake": ep["scores"][t]}, arr([ep["rewards"][t - 1]], f32)))
    return tuple(out)


# ----------------------------------------------------------------------- other worlds
FISH_LOCAL = WorldSpec(
    "fish", "local", tuple(f"fish{i}" for i in range(8)),
    (TeamSpec("fish", tuple(range(8)), "hits", "lower"),),
    28, Box(2, -1.0, 1.0), 1000, (MeasureSpec("hits_per_fish", "fish", "lower"),), 2.5,
)
PREY_TEAM = TeamSpec("prey", (0, 1, 2, 3, 4, 5), "prey_alive", "higher")
PREDATOR_TEAM = TeamSpec("predator", (6, 7), "catches", "higher")
PREY = WorldSpec(
    "prey", "default", tuple(f"prey{i}" for i in range(6)) + ("predator0", "predator1"),
    (PREY_TEAM, PREDATOR_TEAM), 30, Box(2, -1.0, 1.0), 1000,
    (MeasureSpec("pellets", "prey", "higher"),), 3.0,
)
CORRIDOR = WorldSpec(
    "check-discrete", "default", ("agent",), (TeamSpec("agent", (0,), "return", "higher"),),
    6, Discrete(2), 20, (), None,
)
TARGET = WorldSpec(
    "check-continuous", "default", ("agent",), (TeamSpec("agent", (0,), "return", "higher"),),
    1, Box(1, -1.0, 1.0), 20, (), None,
)
rng = np.random.default_rng(0)


def rounded(shape: tuple[int, ...], low: float = -1.0, high: float = 1.0) -> np.ndarray:
    return np.round(rng.uniform(low, high, size=shape), 3).astype(f32)


def corridor_draw(pos: int) -> DrawState:
    objects = [Drawable("exit", -1.0, 0.0, 1.0, None, None), Drawable("exit", 6.0, 0.0, 1.0, None, None)]
    objects += [Drawable("cell", float(i), 0.0, 1.0, None, None) for i in range(6)]
    objects.append(Drawable("agent", float(pos), 0.0, 1.0, "agent", 0))
    return DrawState(8.0, 1.0, tuple(objects))


def target_draw(offset: float) -> DrawState:
    return DrawState(
        2.0, 1.0,
        (Drawable("target", 0.0, 0.0, 0.1, None, None), Drawable("point", offset, 0.0, 0.1, "agent", 0)),
    )


def step_rec(actions: np.ndarray, step: Step, draw: DrawState) -> dict[str, Any]:
    return {"actions": encode(actions), "step": encode(step), "draw": encode(draw)}


# ----------------------------------------------------------------------------- settings
DQN = MethodConfig(
    "dqn",
    {"lr": 0.001, "gamma": 0.99, "epsilon_start": 1.0, "epsilon_end": 0.05,
     "epsilon_decay_steps": 10000, "hidden": 64},
)
PPO_DEFAULTS = {"lr": 0.0003, "gamma": 0.99, "gae_lambda": 0.95, "clip": 0.2,
                "rollout_steps": 2048, "epochs": 10, "hidden": 64}
PPO_LR = MethodConfig("ppo", {**PPO_DEFAULTS, "lr": 0.0001})
CHECK = {"dqn": {"epsilon_decay_steps": 500}}


def snake_config(name: str, seed: int, budget: int) -> RunConfig:
    return RunConfig(name, "snake", "default", {"snake": DQN}, seed, budget, CHECK)


SNAKE_SPEC = snake_spec(1000)
T0 = datetime(2026, 10, 17, 10, 0, tzinfo=UTC)


def run_folder(name: str) -> Path:
    return Path("runs/snake/default") / name


def record(cfg: RunConfig, status: str, failure: Failure | None = None, minutes: float = 41.2) -> RunRecord:
    ended = None if status in ("running", "incomplete") else T0 + timedelta(minutes=minutes)
    return RunRecord(cfg, SNAKE_SPEC, T0, ended, status, failure, run_folder(cfg.name))  # type: ignore[arg-type]


def checkpoint(name: str, pct: int, budget: int) -> Checkpoint:
    eps = 1.0 - 0.95 * pct / 100
    return Checkpoint(
        name, pct, budget * pct // 100, SNAKE_SPEC, {"snake": DQN},
        {"snake": {"epsilon": round(eps, 4), "steps": budget * pct // 100}},
        run_folder(name) / "checkpoints" / f"ckpt_{pct}.pt",
    )


def run_recording(name: str, seed: int, status: str, final: float) -> dict[str, Any]:
    budget = 2000
    cfg = snake_config(name, seed, budget)
    points = 21 if status == "finished" else 9
    evals = [
        EvalPoint(100 * i, {"snake": round(final * i / 20 + 0.01 * seed, 3)}, {}) for i in range(points)
    ]
    episodes = [
        EpisodeResult(int(s), int(l), {"snake": float(f)}, {"snake": float(f) - 1.0}, {})
        for s, l, f in zip(
            np.random.default_rng(seed).integers(0, 1_000_000, 8),
            [40, 55, 61, 80, 95, 120, 133, 150], [0, 1, 1, 2, 2, 3, 4, 4], strict=True,
        )
    ]
    pcts = [0, 50, 100] if status == "finished" else [0]
    return {
        "record": encode(record(cfg, status, minutes=2.5)),
        "episodes": [encode(e) for e in episodes],
        "evals": [encode(e) for e in evals],
        "checkpoints": [encode(checkpoint(name, p, budget)) for p in pcts],
    }


# ------------------------------------------------------------------------------- main
def main() -> None:  # noqa: PLR0915
    # core types
    write("core.ActionSpace", type_schema("core.ActionSpace", ActionSpace),
          {"snake": Discrete(3), "fish": Box(2, -1.0, 1.0)})
    write("core.TeamSpec", type_schema("core.TeamSpec", TeamSpec),
          {"snake": SNAKE_TEAM, "prey": PREY_TEAM, "predator": PREDATOR_TEAM})
    write("core.WorldSpec", type_schema("core.WorldSpec", WorldSpec),
          {"snake": SNAKE_SPEC, "fish-local": FISH_LOCAL, "prey": PREY})
    prey_obs = rounded((8, 30))
    prey_obs[2] = 0.0
