                    step_rec(arr([a], np.int64), STEPS42[t + 1], EP42["draws"][t + 1])
                    for t, a in enumerate(EP42["actions"])
                ],
                "result": encode(snake_result(42, EP42)),
            }
        },
    )
    defs = {}
    call = obj({"obs": Array, "actions": Array}, defs)
    write(
        "core.Policy",
        document("core.Policy", obj({"calls": {"type": "array", "items": call}}, defs), defs),
        {"snake-rule": {"calls": RULE_CALLS}},
    )


def corridor_step(pos: int, reward: float, done: bool) -> Step:
