def writer() -> None:
    defs: dict[str, Any] = {}
    calls_rules = {
        "anyOf": [
            obj({"call": {"const": "episode"}, "result": EpisodeResult}, defs),
            obj({"call": {"const": "eval"}, "point": EvalPoint}, defs),
            obj(
                {
                    "call": {"const": "checkpoint"},
                    "pct": int,
                    "step": int,
                    "state": {"type": "object"},
                    "returns": Checkpoint,
                },
                defs,
            ),
            obj(
                {
                    "call": {"const": "close"},
                    "status": {"type": "string"},
                    "failure": Failure | None,
                    "returns": RunRecord,
                },
                defs,
            ),
        ]
    }
    writer_rec = obj(
        {
            "root": {"type": "string"},
            "config": RunConfig,
            "spec": WorldSpec,
            "calls": {"type": "array", "items": calls_rules},
        },
        defs,
    )
    rec = run_recording("snake-short-s1", 1, "finished", 4.0)
    calls: list[Any] = []
    ckpts = {c["pct"]: c for c in rec["checkpoints"]}
    episodes = iter(rec["episodes"])
    for point in rec["evals"]:
        if point["step"] > 0 and point["step"] % 200 == 0:
            calls.append({"call": "episode", "result": next(episodes, rec["episodes"][-1])})
        calls.append({"call": "eval", "point": point})
        pct = point["step"] * 100 // 2000
        if pct in ckpts:
            c = ckpts[pct]
            calls.append(
                {
                    "call": "checkpoint",
                    "pct": pct,
                    "step": c["step"],
                    "state": c["state"],
                    "returns": c,
                }
            )
    calls.append({"call": "close", "status": "finished", "failure": None, "returns": rec["record"]})
    write(
        "runlog.RunWriter",
        document("runlog.RunWriter", writer_rec, defs),
        {
            "snake-writes": {
                "root": "runs",
                "config": encode(snake_config("snake-short-s1", 1, 2000)),
                "spec": encode(SNAKE_SPEC),
                "calls": calls,
            }
        },
    )


def evaluate() -> None:
    vs_random = Comparison("random", "snake", 12.4, 0.15, 12.25, 0.0001, 0.0002, True)
    vs_rule = Comparison("rule", "snake", 12.4, 9.4, 3.0, 0.0001, 0.0002, True)
    write(
        "evaluate.Comparison",
        type_schema("evaluate.Comparison", Comparison),
        {
            "snake-vs-random": vs_random,
            "snake-vs-rule": Comparison("rule", "snake", 9.9, 9.4, 0.5, 0.08, 0.08, False),
        },
    )
    names = tuple(f"snake-default-s{i}" for i in range(1, 6))
    passing = dict(zip(names, [12.1, 13.0, 11.7, 12.8, 12.4], strict=True))
    failing = dict(zip(names, [14.0, 13.0, 15.0, 12.0, 9.0], strict=True))
    failing_comparisons = (
        Comparison("random", "snake", 12.6, 1.0, 11.6, 0.0001, 0.0002, True),
        Comparison("rule", "snake", 12.6, 10.0, 2.6, 0.0003, 0.0003, True),
    )
    write(
        "evaluate.Summary",
        type_schema("evaluate.Summary", Summary),
        {
            "snake-pass": Summary(
                "snake", "default", "snake", names, 12.4, (11.7, 13.0), passing, 0.15, 9.4,
                (vs_random, vs_rule), Verdict(True, (), 0), None,
            ),
            "snake-failing-run": Summary(
                "snake", "default", "snake", names, 12.6, (9.0, 15.0), failing, 1.0, 10.0,
                failing_comparisons, Verdict(False, ("snake-default-s5",), 0), None,
            ),
            "snake-3-runs": Summary(
                "snake", "default", "snake", names[:3], 12.267, (11.7, 13.0),
                {n: passing[n] for n in names[:3]}, 0.15, 9.4, (), Verdict(False, (), 2), None,
            ),
        },
    )  # fmt: skip


if __name__ == "__main__":
    core_types()
    core_protocols()
    worlds()
    baselines()
    methods()
    train()
    runlog()
    evaluate()

