def snake_result(seed: int, ep: dict[str, Any]) -> EpisodeResult:
    s = ep["scores"][-1]
    return EpisodeResult(
        seed, len(ep["actions"]), {"snake": s}, {"snake": float(sum(ep["rewards"]))}, {}
    )


def frames(ep: dict[str, Any]) -> tuple[Frame, ...]:
    out = [Frame(0, ep["draws"][0], {"snake": 0.0}, arr([0.0], f32))]
    for t in range(1, len(ep["actions"]) + 1):
        out.append(
            Frame(t, ep["draws"][t], {"snake": ep["scores"][t]}, arr([ep["rewards"][t - 1]], f32))
        )
    return tuple(out)


