"""Replay double of `core.World`: serves a recorded episode's steps and drawable states.

Every `reset` starts the recording over, whatever the seed, so a loop can play it many times;
`step` accepts any action inside `spec.action` (an `ActionError` otherwise, never clipped) and
returns the next recorded step; a step after the recorded end raises `RuntimeError`.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import numpy as np

from rllab.core import (
    ActionError,
    Array,
    Box,
    DrawState,
    EpisodeResult,
    Step,
    WorldSpec,
)
from rllab.core.codec import decode

HERE = Path(__file__).parent


class WorldDouble:
    def __init__(self, recording: dict[str, Any]) -> None:
        self.spec = decode(WorldSpec, recording["spec"])
        self.seed: int = recording["seed"]
        self.steps = [decode(Step, recording["reset"]["step"])]
        self.steps += [decode(Step, s["step"]) for s in recording["steps"]]
        self.draws = [decode(DrawState, recording["reset"]["draw"])]
        self.draws += [decode(DrawState, s["draw"]) for s in recording["steps"]]
        self.recorded_actions = [decode(np.ndarray, s["actions"]) for s in recording["steps"]]
        self._result = decode(EpisodeResult, recording["result"])
        self.t = -1
        self.resets: list[int] = []

    def reset(self, seed: int) -> Step:
        self.resets.append(seed)
        self.t = 0
        return self.steps[0]

    def step(self, actions: Array) -> Step:
        if self.t < 0 or self.steps[self.t].done:
            raise RuntimeError("step after the episode ended; call reset")
        self._check(np.asarray(actions))
        self.t += 1
        return self.steps[self.t]

    def result(self) -> EpisodeResult:
        return self._result

    def draw(self) -> DrawState:
        return self.draws[max(self.t, 0)]

    def _check(self, actions: np.ndarray) -> None:
        space = self.spec.action
        for agent, row in zip(self.spec.agents, actions, strict=True):
            if isinstance(space, Box):
                ok = np.shape(row) == (space.dims,) and bool(
                    np.all((row >= space.low) & (row <= space.high))
                )
            else:
                ok = np.ndim(row) == 0 and float(row).is_integer() and 0 <= row < space.n
            if not ok:
                raise ActionError(agent, row)


def recording(case: str) -> dict[str, Any]:
    return json.loads((HERE / "samples" / f"{case}.json").read_text(encoding="utf-8"))


def load(case: str) -> WorldDouble:
    return WorldDouble(recording(case))

