"""Replay double of `core.Policy`: answers each recorded observation with its recorded actions.

Deterministic for a given observation, as the contract requires; an observation the recording
never saw raises `LookupError`. `rng` is accepted and not drawn from.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import numpy as np

from rllab.core import Array
from rllab.core.codec import decode

HERE = Path(__file__).parent


class PolicyDouble:
    def __init__(self, calls: list[dict[str, Any]]) -> None:
        self.calls = [
            (decode(np.ndarray, c["obs"]), decode(np.ndarray, c["actions"])) for c in calls
        ]
        self.seen: list[Array] = []

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        self.seen.append(obs)
        for recorded, actions in self.calls:
            if recorded.shape == obs.shape and np.array_equal(recorded, obs):
                return actions.copy()
        raise LookupError(f"no recorded actions for observation {obs.tolist()}")


def load(case: str) -> PolicyDouble:
    data = json.loads((HERE / "samples" / f"{case}.json").read_text(encoding="utf-8"))
    return PolicyDouble(data["calls"])

